from playwright.sync_api import sync_playwright
from pathlib import Path
p=Path(__file__).resolve().parent
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']); page=b.new_page(viewport={'width':1200,'height':900},accept_downloads=True); errors=[]; network=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:network.append(r.url) if r.url.startswith(('http:','https:')) else None);page.set_content((p/'index.html').read_text()); assert page.locator('#status').inner_text()=='計算完了';assert page.locator('.signature').count()==3;page.locator('summary').first.click();page.screenshot(path=str(p/'desktop.png'),full_page=True)
 with page.expect_download() as d:page.locator('#csv').click()
 content=Path(d.value.path()).read_text();assert content.startswith('signature,sheet,side,left_source,right_source');assert len(content.splitlines())==19
 page.locator('#binding').select_option('right');assert page.locator('#csv').is_disabled();page.locator('#run').click();page.locator('summary').first.click();assert '1 ｜ 白紙' in page.locator('tbody').first.inner_text();page.locator('#chapters').fill('x | 99 | 任意 | 禁止');page.locator('#run').click();assert page.locator('#csv').is_disabled();assert 'ありません' in page.locator('#status').inner_text();page.locator('#chapters').fill('x | 0 | 任意 | 可');page.locator('#run').click();assert '形式' in page.locator('#status').inner_text();page.locator('#reset').click();assert page.locator('#status').inner_text()=='計算完了';page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(p/'mobile.png'),full_page=True);assert not errors and not network;print('Chromium inline: sample, details, CSV download (19 lines), right-binding, invalidation, no solution, invalid input, reset, 390px width PASS; JS errors=0; external HTTP requests=0.');b.close()
